INSERT INTO public.placements (company, role, job_field, languages, skills, notes, package_lpa, location) VALUES ('Google', 'Software Development Engineer (SDE)', 'SWE', '{"C++","Java","Python","Go"}', '{"DSA advanced (400+ LeetCode)","System design basics","C++ or Java","OS, DBMS, CN fundamentals","Python or Go","Behavioural prep (Googleyness)"}', 'Needs 400+ LeetCode problems, strong CS fundamentals and an internship; campus seats are few and mostly go to top colleges, so off-campus and referrals matter a lot. Process: Online assessment (2 DSA rounds), then 3-4 technical interviews covering DSA, system design and Googliness, followed by a hiring committee review.', 24, 'India');
INSERT INTO public.placements (company, role, job_field, languages, skills, notes, package_lpa, location) VALUES ('Microsoft', 'Software Development Engineer (SDE)', 'SWE', '{"C++","Java"}', '{"DSA advanced (300+ LeetCode)","C# or C++ or Java","OS, DBMS, CN fundamentals","System design basics","Azure/cloud basics","OOP design"}', 'Needs strong DSA and CS fundamentals; hires from many colleges through Engage and campus drives, but seats are limited. Process: Online assessment (DSA), then 3-4 interview rounds on DSA, design and behaviour, ending with an HR round.', 22, 'India');
INSERT INTO public.placements (company, role, job_field, languages, skills, notes, package_lpa, location) VALUES ('Amazon', 'Software Development Engineer (SDE)', 'SWE', '{"C++","Java"}', '{"DSA advanced (300+ LeetCode)","Java or C++","OS, DBMS, CN fundamentals","System design basics","Amazon Leadership Principles","AWS basics"}', 'The most reachable of the big three for an average-college student — strong DSA plus Leadership Principles can win it off-campus too. Process: Online assessment (2 DSA + debugging), then 3-4 interviews on DSA, Leadership Principles and system design, including a bar-raiser round.', 21, 'India');
INSERT INTO public.placements (company, role, job_field, languages, skills, notes, package_lpa, location) VALUES ('Adobe', 'Software Development Engineer (SDE)', 'SWE', '{"C++","JavaScript"}', '{"DSA advanced (400+ LeetCode)","C++ (deep)","OS, DBMS, CN fundamentals","OOP design","System design basics","JavaScript + React for web roles"}', 'Needs elite DSA and strong CS fundamentals; very few campus seats outside top colleges, and the internship route is the main door in. Process: Online assessment (DSA + aptitude), then 3-4 technical interviews, ending with an HR round.', 32, 'India');
INSERT INTO public.placements (company, role, job_field, languages, skills, notes, package_lpa, location) VALUES ('Atlassian', 'Software Development Engineer (SDE)', 'SWE', '{"Java","Python"}', '{"DSA advanced (400+ LeetCode)","Java or Python","System design basics","OS, DBMS, CN fundamentals","API design","Behavioural prep (Atlassian values)"}', 'Almost no campus hiring in India — mostly off-campus via HackerRank and referrals; needs elite DSA and values-fit. Process: HackerRank online assessment, a values interview, then 3-4 technical interviews on DSA and design.', 30, 'India');
INSERT INTO public.placements (company, role, job_field, languages, skills, notes, package_lpa, location) VALUES ('Apple', 'Software Development Engineer (SDE)', 'SWE', '{"C++","Swift"}', '{"C/C++ (deep)","Data structures + algorithms","OS fundamentals","Embedded systems basics","Swift for app roles","System design basics"}', 'Very few fresher seats in India, mostly embedded and systems roles; needs deep C/C++ and hardware basics. Process: Online assessment (DSA + CS fundamentals), then 3-4 technical interviews on coding and systems, ending with an HR round.', 28, 'India');
INSERT INTO public.placements (company, role, job_field, languages, skills, notes, package_lpa, location) VALUES ('Oracle', 'Software Development Engineer (SDE)', 'SWE', '{"Java","SQL"}', '{"DSA intermediate (200+ LeetCode)","Java (core + advanced)","SQL + DBMS internals","OS/CN fundamentals","OOP design","Cloud basics"}', 'Reachable with solid DSA and strong DBMS skills; hires from many campuses for Member of Technical Staff roles. Process: Online assessment (aptitude + coding), then 2-3 technical interviews on DSA, DBMS and OS, ending with an HR round.', 15, 'India');
INSERT INTO public.placements (company, role, job_field, languages, skills, notes, package_lpa, location) VALUES ('NVIDIA', 'Software Development Engineer (SDE)', 'SWE', '{"C++","Python"}', '{"C++ (deep)","DSA advanced (300+ LeetCode)","OS + computer architecture","CUDA/GPU basics","Python + ML basics","System design basics"}', 'Needs strong DSA plus C++/systems or AI skills; campus seats are few, and the internship is the main route in. Process: Online assessment (DSA + CS fundamentals), then 3-4 technical interviews on coding and systems or ML, ending with an HR round.', 24, 'India');
INSERT INTO public.placements (company, role, job_field, languages, skills, notes, package_lpa, location) VALUES ('Rubrik', 'Software Development Engineer (SDE)', 'SWE', '{"C++","Python","Go"}', '{"DSA advanced (400+ LeetCode)","C++ or Go","OS + distributed systems","DBMS fundamentals","System design basics","Python"}', 'Tiny fresher intake, almost all through internships; needs elite DSA and systems depth. Process: Online assessment (hard DSA), then 3-4 technical interviews on DSA and systems design, ending with an HR round.', 32, 'India');
